{
  "probability": 0.46,
  "range_low": 0.34,
  "range_high": 0.58,
  "summary": [
    "Historical baseline for a 2/3 majority in Hungary sits near 0.44 (4 of 9 elections), anchored to the reference class of post-1990 parliamentary outcomes.",
    "Early-2026 polling is mixed, with TISZA leading in some surveys and cross-pollster variance creating uncertainty about seat translation.",
    "Structural features of Hungary's electoral system boost the seat share of the leading bloc, raising the prospect of a 2/3 majority if one bloc consolidates a vote lead.",
    "Market signals and multiple updates point to non-negligible but not dominant odds of a 2/3 majority, consistent with a calibrated posterior around mid-0.4s."
  ],
  "confidence": "medium",
  "narrative": "Starting from a 44% historical baseline, recent polls show a contested race with some consolidation around TISZA. The electoral system amplifies the leading bloc, but ongoing uncertainty keeps the probability of a 2/3 majority modest, yielding a calibrated estimate near 46% with a plausible range into the mid-0.5s.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base rate: 4 of 9 Hungarian elections yielded a 2/3 majority (approximately 0.44) since 1990, establishing the reference class anchor for this forecast."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Greater unity within the anti-Orbán bloc reduces the likelihood that any single party or the unified opposition reaches the 133-seat threshold, thereby lowering the probability of a 2/3 majority forming by chance."
      },
      {
        "factor": "Polling momentum and margins (TISZA lead / cross-pollster variance)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Several FEB 2026 polls show TISZA ahead or close; wide cross-pollster variance undermines confidence in a stable 2/3 outcome."
      },
      {
        "factor": "Electoral-system seat amplification bias toward the leading bloc",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Hungary's mixed-member system can translate a vote lead into outsized seat advantages, potentially supporting a 2/3 outcome if a bloc secures a lead in votes."
      },
      {
        "factor": "Prediction markets indicating non-negligible probability of a 2/3 majority",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Markets pricing a government-majority around 0.52 indicate residual belief in a possible 2/3 outcome, updating probability upward from the baseline."
      },
      {
        "factor": "Market and economic signals about governance risk",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Treats governance-change risk as dampening certainty; market implications are uncertain and could complicate a durable 2/3 majority."
      },
      {
        "factor": "Turnout volatility and turnout differentials across blocs",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Turnout fluctuations could swing seat outcomes, but no clear directional bias is established in the current data."
      }
    ],
    "synthesis_rationale": "Calibrated posteriors combine a stable historical anchor with contemporary signals: polls introduce downside risk to a 2/3 outcome, while structural amplification and some market signals provide upside potential. Given the mix, a mid-0.4s posterior with a wide but plausible range captures the balance of evidence and residual uncertainty, avoiding overconfidence in either bloc achieving 133+ seats."
  }
}

